insert into change_headers (id, ts) values (66, '2026-10-11') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (66, 'ru', 'В Калькуляторе полётов перегруппированы параметры. На вкладку «Вселенная» переехали расход дейтерия во вселенной и бонус Генерала к потреблению дейтерия — это настройки сервера, они заполняются вместе со скоростями флота. Поле «Задать скорость флота» теперь в разделе «Корабли», над списком кораблей. Классы альянса «Скупщики» и «Воины» объединены в одну группу «Класс альянса» на вкладке «Общие».<br>В калькуляторах полётов и производства селектор сохранённых настроек называется «Профиль».') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'en', 'The Flight calculator''s parameters have been regrouped. The universe deuterium consumption and the General''s deuterium consumption bonus moved to the "Universe" tab: they are server settings and are filled in together with the fleet speeds. The "Override fleet speed" field is now in the "Ships" section, above the list of ships. The "Traders" and "Warriors" alliance classes are merged into one "Alliance class" group on the "Common" tab.<br>In the Flight and Production calculators, the saved settings selector is now called "Profile".') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'pt', 'Os parâmetros da Calculadora de voo foram reorganizados. O consumo de deutério do universo e o bónus do General ao consumo de deutério passaram para o separador «Universo»: são definições do servidor e são preenchidos juntamente com as velocidades da frota. O campo «Ultrapassar a velocidade da frota» está agora na secção «Naves», por cima da lista de naves. As classes de aliança «Comerciantes» e «Guerreiros» foram reunidas num único grupo «Classe de aliança» no separador «Geral».<br>Nas calculadoras de voo e de produção, o seletor de definições guardadas chama-se agora «Perfil».') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'de', 'Die Parameter des Flugrechners wurden neu gruppiert. Der Deuteriumverbrauch im Universum und der Bonus des Generals auf den Deuteriumverbrauch sind in den Reiter „Universum“ umgezogen: Es sind Servereinstellungen, die zusammen mit den Flottengeschwindigkeiten ausgefüllt werden. Das Feld „Flottengeschwindigkeit außer Kraft setzen“ befindet sich jetzt im Abschnitt „Schiffe“ über der Schiffsliste. Die Allianzklassen „Händler“ und „Krieger“ sind zu einer Gruppe „Allianzklasse“ im Reiter „Allgemein“ zusammengefasst.<br>Im Flug- und im Produktionsrechner heißt die Auswahl gespeicherter Einstellungen jetzt „Profil“.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'pl', 'W Kalkulatorze lotów przegrupowano parametry. Zużycie deuteru we wszechświecie i bonus Generała do zużycia deuteru przeniesiono na kartę „Wszechświat”: to ustawienia serwera, wypełniane razem z prędkościami floty. Pole „Zastąp prędkość floty” znajduje się teraz w sekcji „Statki”, nad listą statków. Klasy sojuszu „Handlarze” i „Wojownicy” połączono w jedną grupę „Klasa sojuszu” na karcie „Ogólne”.<br>W kalkulatorach lotów i produkcji selektor zapisanych ustawień nazywa się teraz „Profil”.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'es', 'Se han reagrupado los parámetros de la Calculadora de vuelo. El consumo de deuterio del universo y la bonificación del General al consumo de deuterio pasan a la pestaña «Universo»: son ajustes del servidor y se rellenan junto con las velocidades de flota. El campo «Anular velocidad de flota» está ahora en la sección «Naves», encima de la lista de naves. Las clases de alianza «Comerciantes» y «Guerreros» se han unido en un solo grupo «Clase de alianza» en la pestaña «General».<br>En las calculadoras de vuelo y de producción, el selector de ajustes guardados se llama ahora «Perfil».') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'fr', 'Les paramètres du Calculateur de vol ont été regroupés autrement. La consommation de deutérium de l''univers et le bonus du Général sur la consommation de deutérium passent dans l''onglet « Univers » : ce sont des réglages du serveur, remplis en même temps que les vitesses de flotte. Le champ « Remplacer la vitesse de la flotte » se trouve désormais dans la section « Vaisseaux », au-dessus de la liste des vaisseaux. Les classes d''alliance « Marchands » et « Guerriers » sont réunies en un seul groupe « Classe d''alliance » dans l''onglet « Général ».<br>Dans les calculateurs de vol et de production, le sélecteur de réglages enregistrés s''appelle désormais « Profil ».') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'it', 'I parametri del Calcolatore di volo sono stati riorganizzati. Il consumo di deuterio dell''universo e il bonus del Generale al consumo di deuterio sono passati alla scheda «Universo»: sono impostazioni del server e vengono compilati insieme alle velocità della flotta. Il campo «Impostare la velocità della flotta» si trova ora nella sezione «Navi», sopra l''elenco delle navi. Le classi alleanza «Commercianti» e «Guerrieri» sono state riunite in un unico gruppo «Classe alleanza» nella scheda «Generale».<br>Nei calcolatori di volo e di produzione il selettore delle impostazioni salvate ora si chiama «Profilo».') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'nl', 'De parameters van de Vluchtcalculator zijn opnieuw ingedeeld. Het deuteriumverbruik in het universum en de bonus van de Generaal op het deuteriumverbruik staan nu op het tabblad "Universum": het zijn serverinstellingen die samen met de vlootsnelheden worden ingevuld. Het veld "Overschrijf vlootsnelheid" staat nu in de sectie "Schepen", boven de lijst met schepen. De alliantieklassen "Handelaars" en "Krijgers" zijn samengevoegd tot één groep "Alliantieklasse" op het tabblad "Algemeen".<br>In de vlucht- en productiecalculator heet de keuzelijst met opgeslagen instellingen nu "Profiel".') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'sk', 'V Kalkulačke letov boli preskupené parametre. Spotreba deutéria vo vesmíre a bonus Generála k spotrebe deutéria sa presunuli na kartu „Vesmír“: sú to nastavenia servera a vypĺňajú sa spolu s rýchlosťami flotily. Pole „Prepísať rýchlosť flotily“ je teraz v sekcii „Lode“, nad zoznamom lodí. Aliančné triedy „Obchodníci“ a „Bojovníci“ sú zlúčené do jednej skupiny „Aliančná trieda“ na karte „Všeobecné“.<br>V kalkulačkách letov a produkcie sa výber uložených nastavení teraz nazýva „Profil“.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'tr', 'Uçuş hesaplayıcısının parametreleri yeniden düzenlendi. Evrendeki döteryum tüketimi ve General''in döteryum tüketimi bonusu "Evren" sekmesine taşındı: bunlar sunucu ayarlarıdır ve filo hızlarıyla birlikte doldurulur. "Filo hızını geçersiz kıl" alanı artık "Gemiler" bölümünde, gemi listesinin üstünde. "Tüccarlar" ve "Savaşçılar" ittifak sınıfları, "Genel" sekmesinde tek bir "İttifak sınıfı" grubunda birleştirildi.<br>Uçuş ve Üretim hesaplayıcılarında kayıtlı ayarlar seçicisinin adı artık "Profil".') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (66, 'bs', 'U Kalkulatoru letova parametri su pregrupisani. Potrošnja deuterija u univerzumu i bonus Generala na potrošnju deuterija premješteni su na karticu „Univerzum“: to su postavke servera i popunjavaju se zajedno s brzinama flote. Polje „Zadaj brzinu flote“ sada se nalazi u odjeljku „Brodovi“, iznad liste brodova. Klase saveza „Trgovci“ i „Ratnici“ spojene su u jednu grupu „Klasa saveza“ na kartici „Opšte“.<br>U kalkulatorima letova i proizvodnje birač sačuvanih postavki sada se zove „Profil“.') on duplicate key update description = values(description);
